CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS settings (id int PRIMARY KEY DEFAULT 1 CHECK(id=1),tournament_name text NOT NULL DEFAULT 'Copa Institucional 6×6',season text NOT NULL DEFAULT '2026',phase text NOT NULL DEFAULT 'Inscripciones abiertas',registration_open boolean NOT NULL DEFAULT true,team_fee numeric(10,2) NOT NULL DEFAULT 8,player_fee numeric(10,2) NOT NULL DEFAULT 2,match_minutes int NOT NULL DEFAULT 20,break_minutes int NOT NULL DEFAULT 5,min_roster int NOT NULL DEFAULT 6,max_roster int NOT NULL DEFAULT 10,min_institutional_on_field int NOT NULL DEFAULT 4,max_external_on_field int NOT NULL DEFAULT 2,min_matches int NOT NULL DEFAULT 3,updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO settings(id) VALUES(1) ON CONFLICT(id) DO NOTHING;
CREATE TABLE IF NOT EXISTS registrations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text UNIQUE NOT NULL,team_name text UNIQUE NOT NULL,color_name text NOT NULL,color_hex text NOT NULL,captain text NOT NULL,captain_id text NOT NULL,phone text NOT NULL,email text NOT NULL,logo_url text,payment_url text,payment_reference text,status text NOT NULL DEFAULT 'Pendiente de revisión',correction_reason text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS registration_players (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),registration_id uuid NOT NULL REFERENCES registrations(id) ON DELETE CASCADE,full_name text NOT NULL,id_number text NOT NULL UNIQUE,player_type text NOT NULL CHECK(player_type IN ('institucional','externo')),career text,shirt_number int,active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS teams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),registration_id uuid UNIQUE REFERENCES registrations(id),name text UNIQUE NOT NULL,color_name text NOT NULL,color_hex text NOT NULL,logo_url text,captain text,group_name text,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS referees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,pin_hash text NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),phase text NOT NULL DEFAULT 'Grupos',group_name text,home_team_id uuid NOT NULL REFERENCES teams(id),away_team_id uuid NOT NULL REFERENCES teams(id),match_date date,match_time time,court text,referee_id uuid REFERENCES referees(id),home_score int CHECK(home_score>=0),away_score int CHECK(away_score>=0),status text NOT NULL DEFAULT 'Programado',round_name text,next_match_id uuid REFERENCES matches(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS match_appearances (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),match_id uuid NOT NULL REFERENCES matches(id) ON DELETE CASCADE,player_id uuid NOT NULL REFERENCES registration_players(id),team_id uuid NOT NULL REFERENCES teams(id),participated boolean NOT NULL DEFAULT true,UNIQUE(match_id,player_id));
CREATE TABLE IF NOT EXISTS cards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),match_id uuid NOT NULL REFERENCES matches(id) ON DELETE CASCADE,player_id uuid NOT NULL REFERENCES registration_players(id),team_id uuid NOT NULL REFERENCES teams(id),card_type text NOT NULL CHECK(card_type IN ('Amarilla','Roja')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS player_replacements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),team_id uuid NOT NULL REFERENCES teams(id),player_out_id uuid NOT NULL REFERENCES registration_players(id),player_in_id uuid NOT NULL REFERENCES registration_players(id),reason text NOT NULL DEFAULT 'Lesión',authorized_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log (id bigserial PRIMARY KEY,actor text NOT NULL,action text NOT NULL,entity_type text NOT NULL,entity_id text,details jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_matches_date ON matches(match_date,match_time); CREATE INDEX IF NOT EXISTS idx_registrations_status ON registrations(status); CREATE INDEX IF NOT EXISTS idx_cards_match ON cards(match_id);
